import { useState, useEffect } from 'react';
import { useSelector } from 'react-redux';
import { usePathname, useRouter } from 'src/routes/hooks';
import { paths } from 'src/routes/paths';
import { SplashScreen } from 'src/components/loading-screen';

import { RoleBasedGuard } from '.';

const signInPaths = { jwt: paths.auth.signIn };

export function AuthGuard({ children }) {
  const router = useRouter();
  const pathname = usePathname();

  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);
  const [isChecking, setIsChecking] = useState(true);
  const [isCheckPermission] = useState(true);

  const createRedirectPath = (currentPath) => {
    const queryString = new URLSearchParams({ returnTo: pathname }).toString();
    return `${currentPath}?${queryString}`;
  };

  const check = () => {
    if (!loggedInTeacher) {
      const redirectPath = createRedirectPath(signInPaths.jwt);
      router.replace(redirectPath);
    } else {
      setIsChecking(false);
    }
  };

  useEffect(() => {
    check();
  }, [loggedInTeacher]);

  if (isChecking) {
    return <SplashScreen />;
  }

  if (!isCheckPermission) {
    return <RoleBasedGuard hasContent sx={{ py: 10 }} />;
  }

  return <>{children}</>;
}

import { useState, useEffect } from 'react';
import { useRouter, useSearchParams } from 'src/routes/hooks';
import { CONFIG } from 'src/global-config';
import { paths } from 'src/routes/paths';
import { SplashScreen } from 'src/components/loading-screen';
import { useSelector } from 'react-redux';

// ----------------------------------------------------------------------

export function GuestGuard({ children }) {
  const router = useRouter();

  const searchParams = useSearchParams();
  const returnTo = searchParams.get('returnTo') || CONFIG.auth.redirectPath;
  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);

  const [isChecking, setIsChecking] = useState(true);
  const checkPermissions = async () => {
    if (loggedInTeacher) {
      if (returnTo === '/' || returnTo === '/dashboard') {
        router.replace(paths.dashboard.teacher.root);
      } else {
        router.replace(returnTo);
      }
      return;
    }
    setIsChecking(false);
  };

  useEffect(() => {
    checkPermissions();
  }, [loggedInTeacher]);

  if (isChecking) {
    return <SplashScreen />;
  }

  return <>{children}</>;
}

import { TextField } from '@mui/material';
import { useEffect, useState } from 'react';
import DatePicker from 'react-datepicker';
import 'react-datepicker/dist/react-datepicker.css';
import dateHelper from 'src/utils/dateHelper';

export default function DateRangePicker({
  showDateRangePicker,
  onDateChanges,
  minDate,
  maxDate,
  resetDuration,
  sDate,
  eDate,
}) {
  const [startDate, setStartDate] = useState(sDate);
  const [endDate, setEndDate] = useState(eDate);
  const [textValue, setTextValue] = useState('mm/dd/yyyy - mm/dd/yyyy');
  const [isDatePickerOpen, setIsDatePickerOpen] = useState(false);

  useEffect(() => {
    if (sDate || eDate) {
      setStartDate(sDate);
      setEndDate(eDate);
      if (sDate && eDate) {
        setTextValue(`${dateHelper.formatDate(sDate)} - ${dateHelper.formatDate(eDate)}`);
      }
    }
  }, [sDate, eDate]);

  useEffect(() => {
    if (showDateRangePicker && resetDuration) {
      setStartDate(null);
      setEndDate(null);
      setTextValue('mm/dd/yyyy - mm/dd/yyyy');
    }
    if (startDate === null && endDate === null) {
      setIsDatePickerOpen(true);
    }
  }, [showDateRangePicker, resetDuration]);

  const onDateChange = (dates) => {
    const [start, end] = dates;
    setStartDate(start);
    setEndDate(end);
    if (start && end) {
      setIsDatePickerOpen(false);
      setTextValue(`${dateHelper.formatDate(start)} - ${dateHelper.formatDate(end)}`);
      onDateChanges(start, end);
    }
  };

  if (!showDateRangePicker) return null;

  return (
    <DatePicker
      open={isDatePickerOpen}
      selected={startDate}
      onChange={onDateChange}
      startDate={startDate}
      endDate={endDate}
      minDate={minDate}
      maxDate={maxDate}
      dateFormat={'MM/dd/yyyy'}
      selectsRange
      showYearDropdown
      showMonthDropdown
      customInput={
        <TextField
          label="Between"
          variant="standard"
          value={textValue}
          sx={{ width: 200 }}
          InputProps={{
            onFocus: () => setIsDatePickerOpen(true),
          }}
        />
      }
    />
  );
}

import dayjs from 'dayjs';
import { useEffect } from 'react';
import { Controller, useFormContext } from 'react-hook-form';
import { DatePicker } from '@mui/x-date-pickers/DatePicker';
import { MobileDateTimePicker } from '@mui/x-date-pickers/MobileDateTimePicker';
import { formatPatterns } from 'src/utils/format-time';
import constants from 'src/utils/constants';
import { MobileTimePicker } from '@mui/x-date-pickers';

// ----------------------------------------------------------------------

export function RHFDatePicker({
  name,
  slotProps,
  allowPastDates = false,
  allowFutureDates = false,
  disabled = false,
  minDateValue,
  ...other
}) {
  const { control } = useFormContext();
  return (
    <Controller
      name={name}
      control={control}
      render={({ field, fieldState: { error } }) => {
        useEffect(() => {
          if (!field.value) {
            field.onChange(dayjs().format('YYYY-MM-DD'));
          }
        }, []);

        const helperText = (error && error.message)
          ? error.message
          : (slotProps && slotProps.textField && slotProps.textField.helperText)
          ? slotProps.textField.helperText
          : undefined;

        const textFieldSlot = (slotProps && slotProps.textField) ? slotProps.textField : {};

        return (
          <DatePicker
            {...field}
            value={field.value ? dayjs(field.value) : dayjs()}
            onChange={(newValue) => {
              if (disabled) return;
              const formatted = newValue && newValue.isValid() ? newValue.format('YYYY-MM-DD') : null;
              field.onChange(formatted);
            }}
            format={constants.dateFormat}
            minDate={minDateValue ? dayjs(minDateValue) : allowPastDates ? undefined : dayjs()}
            maxDate={allowFutureDates ? undefined : dayjs().subtract(0, 'day')}
            slotProps={{
              ...slotProps,
              openPickerButton: {
                disabled: disabled,
              },
              textField: {
                fullWidth: true,
                disabled: disabled,
                error: !!error,
                helperText,
                ...textFieldSlot,
              },
            }}
            {...other}
          />
        );
      }}
    />
  );
}

// ----------------------------------------------------------------------

export function RHFMobileDateTimePicker({ name, slotProps, ...other }) {
  const { control } = useFormContext();

  return (
    <Controller
      name={name}
      control={control}
      render={({ field, fieldState: { error } }) => {
        const helperText = (error && error.message)
          ? error.message
          : (slotProps && slotProps.textField && slotProps.textField.helperText)
          ? slotProps.textField.helperText
          : undefined;

        const textFieldSlot = (slotProps && slotProps.textField) ? slotProps.textField : {};

        return (
          <MobileDateTimePicker
            {...field}
            value={field.value ? dayjs(field.value) : dayjs()}
            onChange={(newValue) => field.onChange(dayjs(newValue).format())}
            format={formatPatterns.split.dateTime}
            slotProps={{
              textField: {
                fullWidth: true,
                error: !!error,
                helperText,
                ...textFieldSlot,
              },
              ...slotProps,
            }}
            {...other}
          />
        );
      }}
    />
  );
}

export function RHFMobileTimePicker({ name, slotProps, disabled = false, ...other }) {
  const { control } = useFormContext();

  return (
    <Controller
      name={name}
      control={control}
      render={({ field, fieldState: { error } }) => {
        const displayValue = field.value ? dayjs(field.value, constants.timeFormat) : null;

        const helperText = (error && error.message)
          ? error.message
          : (slotProps && slotProps.textField && slotProps.textField.helperText)
          ? slotProps.textField.helperText
          : undefined;

        const textFieldSlot = (slotProps && slotProps.textField) ? slotProps.textField : {};

        return (
          <MobileTimePicker
            {...field}
            value={displayValue}
            onChange={(newValue) => {
              const formatted =
                newValue && dayjs(newValue).isValid()
                  ? dayjs(newValue).format(constants.timeFormat)
                  : null;
              field.onChange(formatted);
            }}
            slotProps={{
              ...slotProps,
              textField: {
                fullWidth: true,
                disabled: disabled,
                error: !!error,
                helperText,
                ...textFieldSlot,
              },
            }}
            {...other}
          />
        );
      }}
    />
  );
}

import { useBoolean } from 'minimal-shared/hooks';
import { mergeClasses } from 'minimal-shared/utils';
import Collapse from '@mui/material/Collapse';
import { useTheme } from '@mui/material/styles';
import { useSelector } from 'react-redux';

import { Nav, NavUl, NavLi, NavSubheader } from '../components';
import { navSectionClasses, navSectionCssVars } from '../styles';

import { NavList } from './nav-list';

// ----------------------------------------------------------------------

export function NavSectionVertical({
  sx,
  data,
  render,
  className,
  slotProps,
  currentRole,
  enabledRootRedirect,
  cssVars: overridesVars,
  ...other
}) {
  const theme = useTheme();
  const { loggedInTeacher } = useSelector((state) => state.AuthReducer);
  const cssVars = { ...navSectionCssVars.vertical(theme), ...overridesVars };

  return (
    <Nav
      className={mergeClasses([navSectionClasses.vertical, className])}
      sx={[{ ...cssVars }, ...(Array.isArray(sx) ? sx : [sx])]}
      {...other}
    >
      <NavUl sx={{ flex: '1 1 auto', gap: 'var(--nav-item-gap)' }}>
        {data.map((group) => (
          <Group
            key={group.subheader ?? group.items[0].title}
            subheader={group.subheader}
            items={group.items}
            render={render}
            slotProps={slotProps}
            currentRole={currentRole}
            enabledRootRedirect={enabledRootRedirect}
            loggedInTeacher={loggedInTeacher}
          />
        ))}
      </NavUl>
    </Nav>
  );
}

// ----------------------------------------------------------------------

function Group({
  items,
  render,
  subheader,
  slotProps,
  currentRole,
  enabledRootRedirect,
}) {
  const groupOpen = useBoolean(true);

  const renderContent = () => (
    <NavUl sx={{ gap: 'var(--nav-item-gap)' }}>
      {items.map((list) => (
        <NavList
          key={list.title}
          data={list}
          render={render}
          depth={1}
          slotProps={slotProps}
          currentRole={currentRole}
          enabledRootRedirect={enabledRootRedirect}
        />
      ))}
    </NavUl>
  );

  return (
    <NavLi>
      {subheader ? (
        <>
          <NavSubheader
            data-title={subheader}
            open={groupOpen.value}
            onClick={groupOpen.onToggle}
            sx={slotProps?.subheader}
          >
            {subheader}
          </NavSubheader>

          <Collapse in={groupOpen.value}>{renderContent()}</Collapse>
        </>
      ) : (
        renderContent()
      )}
    </NavLi>
  );
}

import { isEqual } from 'es-toolkit';
import { useLocalStorage } from 'minimal-shared/hooks';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSelector } from 'react-redux';

import { SETTINGS_STORAGE_KEY } from '../settings-config';

import { SettingsContext } from './settings-context';

// ----------------------------------------------------------------------

export function SettingsProvider({
  children,
  defaultSettings: baseSettings,
  storageKey = SETTINGS_STORAGE_KEY,
}) {
  const { tenantDetail } = useSelector((state) => state.AuthReducer);
  const mergedDefaultSettings = useMemo(() => {
    const tenantPrimary = tenantDetail?.primaryColor;
    const configPrimary = baseSettings?.primaryColor || 'preset3';

    return {
      ...(baseSettings || {}),
      primaryColor: tenantPrimary || configPrimary,
    };
  }, [baseSettings, tenantDetail?.primaryColor]);

  const { state, setState, resetState, setField } = useLocalStorage(
    storageKey,
    mergedDefaultSettings
  );

  useEffect(() => {
    if (tenantDetail?.primaryColor) {
      setField('primaryColor', tenantDetail.primaryColor);
    }
  }, [tenantDetail?.primaryColor]);

  const [openDrawer, setOpenDrawer] = useState(false);

  const onToggleDrawer = useCallback(() => {
    setOpenDrawer((prev) => !prev);
  }, []);

  const onCloseDrawer = useCallback(() => {
    setOpenDrawer(false);
  }, []);

  const canReset = !isEqual(state, mergedDefaultSettings);

  const onReset = useCallback(() => {
    resetState(mergedDefaultSettings);
  }, [mergedDefaultSettings, resetState]);

  const memoizedValue = useMemo(
    () => ({
      canReset,
      onReset,
      openDrawer,
      onCloseDrawer,
      onToggleDrawer,
      state,
      setState,
      setField,
    }),
    [canReset, onReset, openDrawer, onCloseDrawer, onToggleDrawer, state, setField, setState]
  );

  return <SettingsContext.Provider value={memoizedValue}>{children}</SettingsContext.Provider>;
}

import { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Box,
  Card,
  Table,
  Stack,
  Button,
  TableRow,
  TableBody,
  TableCell,
  TableContainer,
  LinearProgress,
} from '@mui/material';
import { useSetState } from 'minimal-shared/hooks';
import { paths } from 'src/routes/paths';
import ApiService from 'src/services/ApiService';
import { toast } from 'src/components/snackbar';
import { Iconify } from 'src/components/iconify';
import { ConfirmDialog } from 'src/components/custom-dialog';
import { DashboardContent } from 'src/layouts/dashboard';
import { CustomBreadcrumbs } from 'src/components/custom-breadcrumbs';
import { TableToolbar } from 'src/sections/table-toolbar';
import {
  getComparator,
  rowInPage,
  TableHeadCustom,
  TableNoData,
  useTable,
} from 'src/components/table';

import { NoticeFormDialog } from '../notice-form-dialog';
import { AnnouncementTableRow } from '../announcement-table-row';

const FILTEREDTABLEHEAD = [
  { id: 'title', label: 'Title', width: '20%' },
  { id: 'message', label: 'Message', width: '35%', sortBy: false },
  { id: 'audience', label: 'Audience', width: '15%' },
  { id: 'publishDate', label: 'Publish Date', width: '15%' },
  { id: 'updatedDate', label: 'Last Update', width: '15%' },
];

const TABLEHEAD = [
  ...FILTEREDTABLEHEAD,
  { id: '', label: 'Action', width: '10%', sortBy: false, sx: { textAlign: 'center' } },
];

export function AnnouncementsView() {
  const table = useTable({ defaultOrderBy: 'updatedDate', defaultOrder: 'desc' });
  const [isLoading, setIsLoading] = useState(false);
  const [notices, setNotices] = useState([]);
  const [classes, setClasses] = useState([]);

  const [formOpen, setFormOpen] = useState(false);
  const [formNotice, setFormNotice] = useState(null);
  const [deleteNotice, setDeleteNotice] = useState(null);

  const filters = useSetState({ search: '', classId: '' });
  const { state: currentFilters, setState: updateFilters } = filters;

  const dataInPage = rowInPage(notices, table.page, table.rowsPerPage);

  const loadNotices = useCallback(async () => {
    setIsLoading(true);
    const res = await ApiService.getAnnouncementListAsync();
    setNotices(res && res.data ? res.data : []);
    setIsLoading(false);
  }, []);

  useEffect(() => {
    loadNotices();
    (async () => {
      const res = await ApiService.getClassListAsync();
      setClasses(res && res.data ? res.data : []);
    })();
  }, [loadNotices]);

  const openNew = () => {
    setFormNotice(null);
    setFormOpen(true);
  };

  const openEdit = (notice) => {
    setFormNotice(notice);
    setFormOpen(true);
  };

  const handleDelete = async (notice) => {
    if (!notice) return;
    const res = await ApiService.deleteAnnouncementAsync(notice.announcementId);
    if (res && res.data) {
      setNotices((prev) => prev.filter((row) => row.announcementId !== notice.announcementId));
      toast.success('Announcement deleted.');
      table.onUpdatePageDeleteRow(dataInPage.length);
    } else if (res && res.errors && res.errors.length) {
      toast.error(res.errors[0].msg);
    }
  };

  const dataFiltered = useMemo(() => {
    const { search, classId } = currentFilters;
    const stabilizedThis = notices.map((el, idx) => [el, idx]);
    stabilizedThis.sort((a, b) => {
      const order = getComparator(table.order, table.orderBy)(a[0], b[0]);
      if (order !== 0) return order;
      return a[1] - b[1];
    });
    let filteredData = stabilizedThis.map((el) => el[0]);
    if (search) {
      const lower = search.toLowerCase();
      filteredData = filteredData.filter((notice) => {
        return (
          (notice.title && notice.title.toLowerCase().includes(lower)) ||
          (notice.message && notice.message.toLowerCase().includes(lower))
        );
      });
    }
    if (classId) {
      filteredData = filteredData.filter((notice) => {
        return notice.classId == classId;
      });
    }
    return filteredData;
  }, [notices, table.order, table.orderBy, currentFilters]);

  const handleFilterChange = (newValue, key = 'search') => {
    updateFilters({ [key]: newValue });
  };

  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Announcements"
        links={[
          { name: 'Dashboard', href: '' },
          { name: 'Announcements', href: paths.dashboard.announcement.root },
        ]}
        action={
          <Button
            variant="contained"
            color="primary"
            startIcon={<Iconify icon="mingcute:add-line" />}
            onClick={openNew}
          >
            New Announcement
          </Button>
        }
        sx={{ mb: { xs: 2, md: 2 } }}
      />

      <Card>
        <TableToolbar
          filters={filters}
          onFilterChange={handleFilterChange}
          placeholder="Search By Title or Message"
        ></TableToolbar>

        <TableContainer sx={{ height: 'calc(100vh - 40vh)' }}>
          <Box sx={{ position: 'relative' }}>
            <Table stickyHeader size={table.dense ? 'small' : 'medium'}>
              <TableHeadCustom
                order={table.order}
                orderBy={table.orderBy}
                headCells={TABLEHEAD}
                rowCount={dataFiltered.length}
                numSelected={table.selected.length}
                onSort={table.onSort}
              />

              {isLoading ? (
                <TableBody>
                  <TableRow>
                    <TableCell colSpan={TABLEHEAD.length}>
                      <Box
                        sx={{
                          display: 'flex',
                          justifyContent: 'center',
                          alignItems: 'center',
                          height: '100%',
                          width: '100%',
                        }}
                      >
                        <Stack alignItems="center" justifyContent="center" sx={{ width: '100%' }}>
                          <LinearProgress sx={{ width: '50%', maxWidth: 360 }} />
                        </Stack>
                      </Box>
                    </TableCell>
                  </TableRow>
                </TableBody>
              ) : (
                <TableBody>
                  <TableNoData
                    label="No data found"
                    notFound={dataFiltered.length <= 0}
                  />
                  {dataFiltered.map((row) => (
                    <AnnouncementTableRow
                      key={row.announcementId}
                      row={row}
                      onEditRow={() => openEdit(row)}
                      onDeleteRow={() => setDeleteNotice(row)}
                    />
                  ))}
                </TableBody>
              )}
            </Table>
          </Box>
        </TableContainer>
      </Card>

      <NoticeFormDialog
        open={formOpen}
        onClose={() => setFormOpen(false)}
        notice={formNotice}
        classes={classes}
        onSuccess={loadNotices}
      />

      <ConfirmDialog
        open={Boolean(deleteNotice)}
        onClose={() => setDeleteNotice(null)}
        title="Delete Announcement"
        content={
          deleteNotice && deleteNotice.title
            ? `Are you sure you want to delete "${deleteNotice.title}"?`
            : 'Are you sure you want to delete this announcement?'
        }
        action={
          <Button
            variant="contained"
            color="error"
            onClick={() => {
              handleDelete(deleteNotice);
              setDeleteNotice(null);
            }}
          >
            Delete
          </Button>
        }
      />
    </DashboardContent>
  );
}

import { useState } from 'react';
import { useForm } from 'react-hook-form';
import {
  Box,
  Table,
  Stack,
  Button,
  TableRow,
  TableBody,
  TableCell,
  TableHead,
  Typography,
  CircularProgress,
  TableContainer,
} from '@mui/material';
import ApiService from 'src/services/ApiService';
import { Form, Field } from 'src/components/hook-form';

const firstOfMonth = () => `${new Date().toISOString().slice(0, 7)}-01`;

export function AttendanceReport({ selectedClass }) {
  const [summary, setSummary] = useState([]);
  const [loading, setLoading] = useState(false);
  const [loaded, setLoaded] = useState(false);

  const methods = useForm({
    defaultValues: {
      fromDate: firstOfMonth(),
      toDate: '',
    },
  });

  const { watch } = methods;
  const fromDate = watch('fromDate');
  const toDate = watch('toDate');

  const loadSummary = async () => {
    if (!selectedClass) return;
    setLoading(true);
    const res = await ApiService.getAttendanceSummaryAsync(
      selectedClass.classId,
      selectedClass.sectionId,
      fromDate,
      toDate
    );
    setSummary(res && res.data ? res.data : []);
    setLoaded(true);
    setLoading(false);
  };

  return (
    <Form methods={methods}>
      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        spacing={2}
        alignItems={{ sm: 'center' }}
        sx={{ p: 2 }}
      >
        <Field.DatePicker
          name="fromDate"
          label="From"
          allowFutureDates
          allowPastDates
          slotProps={{ textField: { size: 'small', fullWidth: false } }}
        />
        <Field.DatePicker
          name="toDate"
          label="To"
          allowFutureDates
          allowPastDates
          slotProps={{ textField: { size: 'small', fullWidth: false } }}
        />
        <Button variant="contained" color="primary" onClick={loadSummary} disabled={!selectedClass}>
          Load Report
        </Button>
      </Stack>

      {loading ? (
        <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
          <CircularProgress />
        </Box>
      ) : summary.length === 0 ? (
        <Box sx={{ py: 8, textAlign: 'center' }}>
          <Typography variant="body2" sx={{ color: 'text.secondary' }}>
            {loaded
              ? 'No data found'
              : 'Select a date range, then click “Load Report”.'}
          </Typography>
        </Box>
      ) : (
        <TableContainer sx={{ overflowX: 'auto' }}>
          <Table>
            <TableHead>
              <TableRow>
                <TableCell sx={{ width: 90 }}>Roll No</TableCell>
                <TableCell>Student</TableCell>
                <TableCell align="center">Present</TableCell>
                <TableCell align="center">Absent</TableCell>
                <TableCell align="center">Leave</TableCell>
                <TableCell align="center">Half</TableCell>
                <TableCell align="center">Total</TableCell>
                <TableCell align="center">%</TableCell>
              </TableRow>
            </TableHead>
            <TableBody>
              {summary.map((s) => (
                <TableRow key={s.studentId} hover>
                  <TableCell>{s.rollNo}</TableCell>
                  <TableCell>{s.studentName}</TableCell>
                  <TableCell align="center">{s.presentCount}</TableCell>
                  <TableCell align="center">{s.absentCount}</TableCell>
                  <TableCell align="center">{s.lateCount}</TableCell>
                  <TableCell align="center">{s.halfDayCount}</TableCell>
                  <TableCell align="center">{s.totalMarked}</TableCell>
                  <TableCell
                    align="center"
                    sx={{
                      fontWeight: 700,
                      color: s.presentPercentage >= 75 ? 'success.main' : 'error.main',
                    }}
                  >
                    {s.presentPercentage}%
                  </TableCell>
                </TableRow>
              ))}
            </TableBody>
          </Table>
        </TableContainer>
      )}
    </Form>
  );
}

import { useState, useEffect } from 'react';
import { Tab, Tabs, Card, Stack, Select, MenuItem } from '@mui/material';
import { paths } from 'src/routes/paths';
import ApiService from 'src/services/ApiService';
import { DashboardContent } from 'src/layouts/dashboard';
import { CustomBreadcrumbs } from 'src/components/custom-breadcrumbs';
import { formatClassSection } from 'src/utils/utils';

import { AttendanceMark } from '../attendance-mark';
import { AttendanceReport } from '../attendance-report';


function classKey(option) {
  if (!option) return '';
  return `${option.classId}-${option.sectionId !== null && option.sectionId !== undefined ? option.sectionId : 'null'}`;
}

export function AttendanceView() {
  const [classSections, setClassSections] = useState([]);
  const [selectedClass, setSelectedClass] = useState(null);
  const [tab, setTab] = useState('mark');

  useEffect(() => {
    async function loadClasses() {
      const res = await ApiService.getAllClassMasterSectionsAsync();
      const list = res && res.data ? res.data : [];
      setClassSections(list);
      if (list.length > 0) setSelectedClass(list[0]);
    }
    loadClasses();
  }, []);

  const handleSelectClass = (value) => {
    setSelectedClass(classSections.find((c) => classKey(c) === value) || null);
  };

  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Attendance"
        links={[
          { name: 'Dashboard', href: '' },
          { name: 'Attendance', href: paths.dashboard.attendance.root },
        ]}
        sx={{ mb: 4 }}
      />

      <Card sx={{ mb: 3, p: 2 }}>
        <Stack direction={{ xs: 'column', sm: 'row' }} spacing={2} alignItems={{ sm: 'center' }}>
          <Select
            size="small"
            value={classKey(selectedClass)}
            onChange={(e) => handleSelectClass(e.target.value)}
            displayEmpty
          >
            <MenuItem value="" disabled>
              <em>Select Class & Section</em>
            </MenuItem>
            {classSections.map((option) => (
              <MenuItem key={classKey(option)} value={classKey(option)}>
                {formatClassSection(option)}
              </MenuItem>
            ))}
          </Select>
        </Stack>
      </Card>

      <Card>
        <Tabs
          value={tab}
          onChange={(e, v) => setTab(v)}
          sx={{ px: 2, borderBottom: 1, borderColor: 'divider' }}
        >
          <Tab value="mark" label="Mark Attendance" />
          <Tab value="report" label="Report" />
        </Tabs>

        {tab === 'mark' ? (
          <AttendanceMark selectedClass={selectedClass} />
        ) : (
          <AttendanceReport selectedClass={selectedClass} />
        )}
      </Card>
    </DashboardContent>
  );
}

import { zodResolver } from '@hookform/resolvers/zod';
import { LoadingButton } from '@mui/lab';
import {
  Autocomplete,
  Button,
  Checkbox,
  Chip,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
  TextField,
} from '@mui/material';
import { useEffect, useState } from 'react';
import { Controller, FormProvider, useForm } from 'react-hook-form';
import { useSelector } from 'react-redux';
import { z as zod } from 'zod';
import { Field } from 'src/components/hook-form';
import { toast } from 'src/components/snackbar';
import ApiService from 'src/services/ApiService';

const getClassSchema = (showHostel) =>
  zod.object({
    className: zod.string().trim().min(1, { message: 'Class Name is required.' }),
    annualFee: zod.coerce.number().positive({ message: 'Annual Fee is required.' }),
    hostelFee: showHostel
      ? zod.coerce.number().positive({ message: 'Hostel Fee is required.' })
      : zod.coerce.number().nullable().optional(),
    sections: zod.string().trim().optional(),
    subjectIds: zod.array(zod.number()).min(1, { message: 'Please select at least one subject.' }),
  });

const defaultValues = {
  className: '',
  annualFee: '',
  hostelFee: '',
  sections: '',
  subjectIds: [],
};

export function ClassDialog({ id, open, onClose, onSuccess }) {
  const tenant = useSelector((state) => state.AuthReducer.tenantDetail);
  const showHostel = Boolean(tenant && tenant.isHostel);
  const [isLoading, setIsLoading] = useState(false);
  const [isLoadingData, setIsLoadingData] = useState(false);
  const [subjects, setSubjects] = useState([]);

  const methods = useForm({
    resolver: zodResolver(getClassSchema(showHostel)),
    defaultValues,
  });

  const {
    reset,
    setError,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  useEffect(() => {
    if (!open) return;
    loadSubjects();
    if (id) {
      loadClass();
    } else {
      reset(defaultValues);
    }
  }, [id, open]);

  const loadSubjects = async () => {
    const { data } = await ApiService.getSubjectAsync();
    if (data) {
      setSubjects(data);
    }
  };

  const loadClass = async () => {
    setIsLoadingData(true);
    try {
      const { data } = await ApiService.getClassDataByIdAsync(id);

      if (data) {
        reset({
          className: data.className,
          annualFee: data.annualFee,
          hostelFee: data.hostelFee != null ? data.hostelFee : '',
          sections: data.sections ? data.sections.join(', ') : '',
          subjectIds: data.subjectIds || [],
        });
      }
    } finally {
      setIsLoadingData(false);
    }
  };

  const onSubmit = handleSubmit(async (values) => {
    setIsLoading(true);

    const payload = {
      className: values.className,
      annualFee:
        values.annualFee === '' || values.annualFee == null ? null : Number(values.annualFee),
      hostelFee:
        values.hostelFee === '' || values.hostelFee == null ? null : Number(values.hostelFee),
      sections: values.sections
        .split(',')
        .map((x) => x.trim())
        .filter(Boolean),
      subjectIds: values.subjectIds,
      ...(id && { classId: Number(id) }),
    };
    const response = await ApiService.saveClassAsync(payload);

    if (response.data) {
      toast.success(id ? 'Class updated successfully.' : 'Class created successfully.');
      if (onSuccess) onSuccess();
      onClose();
      reset(defaultValues);
    } else if (response.errors) {
      response.errors.forEach((error) => {
        setError(error.param, {
          message: error.msg,
        });
      });
    }

    setIsLoading(false);
  });

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>{id ? 'Edit Class' : 'New Class'}</DialogTitle>

      {isLoadingData ? (
        <DialogContent
          sx={{
            display: 'flex',
            justifyContent: 'center',
            py: 5,
          }}
        >
          <CircularProgress />
        </DialogContent>
      ) : (
        <FormProvider {...methods}>
          <DialogContent>
            <Stack spacing={2} sx={{ mt: 1 }}>
              <Field.Text name="className" label="Class Name" fullWidth />

              <Field.Text name="annualFee" label="Annual Fee" type="number" fullWidth />

              {showHostel && (
                <Field.Text name="hostelFee" label="Hostel Fee" type="number" fullWidth />
              )}

              <Field.Text name="sections" label="Sections" placeholder="A, B, C" fullWidth />

              <Controller
                name="subjectIds"
                control={methods.control}
                render={({ field }) => (
                  <Autocomplete
                    {...field}
                    fullWidth
                    multiple
                    disableCloseOnSelect
                    options={subjects}
                    value={subjects.filter((subject) =>
                      (field.value || []).includes(subject.subjectId)
                    )}
                    getOptionLabel={(option) => option.subjectName}
                    isOptionEqualToValue={(option, value) => option.subjectId === value.subjectId}
                    onChange={(event, newValue) => {
                      field.onChange(newValue.map((item) => item.subjectId));
                    }}
                    renderInput={(params) => (
                      <TextField
                        {...params}
                        label="Subjects"
                        placeholder="Select Subjects"
                        error={!!methods.formState.errors.subjectIds}
                        helperText={
                          methods.formState.errors.subjectIds
                            ? methods.formState.errors.subjectIds.message
                            : ''
                        }
                      />
                    )}
                    renderOption={(props, option) => {
                      const isSelected = (field.value || []).includes(option.subjectId);

                      return (
                        <li {...props} key={option.subjectId}>
                          <Checkbox size="small" disableRipple checked={isSelected} />
                          {option.subjectName}
                        </li>
                      );
                    }}
                    renderTags={(selected, getTagProps) =>
                      selected.map((option, index) => (
                        <Chip
                          {...getTagProps({ index })}
                          key={option.subjectId}
                          label={option.subjectName}
                          size="small"
                          variant="soft"
                        />
                      ))
                    }
                  />
                )}
              />
            </Stack>
          </DialogContent>

          <DialogActions sx={{ justifyContent: 'flex-start' }}>
            <LoadingButton
              variant="contained"
              color="primary"
              loading={isSubmitting || isLoading}
              onClick={onSubmit}
            >
              Save
            </LoadingButton>
            <Button variant="outlined" color="error" onClick={onClose}>
              Cancel
            </Button>
          </DialogActions>
        </FormProvider>
      )}
    </Dialog>
  );
}

import { zodResolver } from '@hookform/resolvers/zod';
import { LoadingButton } from '@mui/lab';
import {
  Button,
  CircularProgress,
  Dialog,
  DialogActions,
  DialogContent,
  DialogTitle,
  Stack,
} from '@mui/material';
import { useState } from 'react';
import { FormProvider, useForm } from 'react-hook-form';
import { z as zod } from 'zod';
import { Field } from 'src/components/hook-form';
import { toast } from 'src/components/snackbar';
import ApiService from 'src/services/ApiService';

const SubjectSchema = zod.object({
  subjectName: zod.string().trim().min(1, { message: 'Subject Name is required.' }),
  subjectCode: zod.string().trim().min(1, { message: 'Subject Code is required.' }),
});

const defaultValues = {
  subjectName: '',
  subjectCode: '',
};

export function SubjectDialog({ id, open, onClose, onSuccess }) {
  const [isLoading, setIsLoading] = useState(false);

  const methods = useForm({
    resolver: zodResolver(SubjectSchema),
    defaultValues,
  });

  const {
    reset,
    setError,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  const onSubmit = handleSubmit(async (values) => {
    setIsLoading(true);

    const payload = {
      subjectName: values.subjectName,
      subjectCode: values.subjectCode,
    };

    const response = await ApiService.saveSubjectAsync(payload);

    if (response.data) {
      toast.success(id ? 'Subject updated successfully.' : 'Subject created successfully.');
      if (onSuccess) onSuccess();
      onClose();
      reset(defaultValues);
    } else if (response.errors) {
      response.errors.forEach((error) => {
        setError(error.param, {
          message: error.msg,
        });
      });
    }

    setIsLoading(false);
  });

  return (
    <Dialog open={open} onClose={onClose} fullWidth maxWidth="sm">
      <DialogTitle>{id ? 'Edit Subject' : 'Add Subject'}</DialogTitle>

      {isLoadingData ? (
        <DialogContent
          sx={{
            display: 'flex',
            justifyContent: 'center',
            py: 5,
          }}
