          <DialogActions sx={{ justifyContent: 'flex-start' }}>
            <LoadingButton
              variant="contained"
              color="primary"
              loading={isSubmitting || isLoading}
              onClick={onSubmit}
            >
              Save
            </LoadingButton>
            <Button variant="outlined" color="error" onClick={onClose}>
              Cancel
            </Button>
          </DialogActions>
        </FormProvider>
      )}
    </Dialog>
  );
}

import { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Card,
  Table,
  Stack,
  Button,
  Select,
  Tooltip,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  TableHead,
  IconButton,
  Typography,
  CircularProgress,
  TableContainer,
} from '@mui/material';
import { paths } from 'src/routes/paths';
import { RouterLink } from 'src/routes/components';
import ApiService from 'src/services/ApiService';
import dateHelper from 'src/utils/dateHelper';
import { toast } from 'src/components/snackbar';
import { Iconify } from 'src/components/iconify';
import { DashboardContent } from 'src/layouts/dashboard';
import { ConfirmDialog } from 'src/components/custom-dialog';
import { formatClassSection } from 'src/utils/utils';


function isExamEnded(exam) {
  const lastDate = exam.endDate || exam.examDate;
  if (!lastDate) return false;
  return lastDate < new Date().toISOString().slice(0, 10);
}

function classKey(option) {
  if (!option) return '';
  return `${option.classId}-${option.sectionId != null ? option.sectionId : 'null'}`;
}

export function ExamsView() {
  const [classSections, setClassSections] = useState([]);
  const [selectedClass, setSelectedClass] = useState(null);
  const [exams, setExams] = useState([]);
  const [loading, setLoading] = useState(false);

  const [deleteExam, setDeleteExam] = useState(null);

  useEffect(() => {
    async function loadClasses() {
      const res = await ApiService.getAllClassMasterSectionsAsync();
      const list = res && res.data ? res.data : [];
      setClassSections(list);
      if (list.length > 0) setSelectedClass(list[0]);
    }
    loadClasses();
  }, []);

  const loadExams = useCallback(async () => {
    if (!selectedClass) {
      setExams([]);
      return;
    }
    setLoading(true);
    const res = await ApiService.getExamListAsync(selectedClass.classId);
    setExams(res && res.data ? res.data : []);
    setLoading(false);
  }, [selectedClass]);

  useEffect(() => {
    loadExams();
  }, [loadExams]);

  const handleSelectClass = (value) => {
    setSelectedClass(classSections.find((c) => classKey(c) === value) || null);
  };

  const handleDelete = async (exam) => {
    if (!exam) return;
    const res = await ApiService.deleteExamAsync(exam.examId);
    if (res && res.data) {
      toast.success('Exam deleted.');
      loadExams();
    } else if (res && res.errors && res.errors.length) {
      toast.error(res.errors[0].msg);
    }
  };

  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Exams"
        links={[
          { name: 'Dashboard', href: '' },
          { name: 'Exams', href: paths.dashboard.exam.root },
        ]}
        action={
          <Button
            component={RouterLink}
            href={paths.dashboard.exam.new}
            state={{ classId: selectedClass ? selectedClass.classId : null }}
            variant="contained"
            color="primary"
            startIcon={<Iconify icon="mingcute:add-line" />}
          >
            New Exam
          </Button>
        }
        sx={{ mb: 4 }}
      />

      <Card sx={{ mb: 3, p: 2 }}>
        <Select
          size="small"
          value={classKey(selectedClass)}
          onChange={(e) => handleSelectClass(e.target.value)}
          displayEmpty
          sx={{ minWidth: 220 }}
        >
          <MenuItem value="" disabled>
            <em>Select Class & Section</em>
          </MenuItem>
          {classSections.map((option) => (
            <MenuItem key={classKey(option)} value={classKey(option)}>
              {formatClassSection(option)}
            </MenuItem>
          ))}
        </Select>
      </Card>

      <Card>
        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', py: 8 }}>
            <CircularProgress />
          </Box>
        ) : exams.length === 0 ? (
          <Box sx={{ py: 8, textAlign: 'center' }}>
            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
              No data found
            </Typography>
          </Box>
        ) : (
          <TableContainer sx={{ overflowX: 'auto' }}>
            <Table>
              <TableHead>
                <TableRow>
                  <TableCell>Exam</TableCell>
                  <TableCell align="center">Start Date</TableCell>
                  <TableCell align="center">End Date</TableCell>
                  <TableCell>Updated By</TableCell>
                  <TableCell align="center" sx={{ width: 200 }}>
                    Actions
                  </TableCell>
                </TableRow>
              </TableHead>
              <TableBody>
                {exams.map((exam) => (
                  <TableRow key={exam.examId} hover>
                    <TableCell>{exam.examName}</TableCell>
                    <TableCell align="center">
                      {exam.startDate ? dateHelper.formatDate(exam.startDate) : '-'}
                    </TableCell>
                    <TableCell align="center">
                      {exam.endDate ? dateHelper.formatDate(exam.endDate) : '-'}
                    </TableCell>
                    <TableCell>
                      <Stack sx={{ typography: 'body2' }}>
                        <Box component="span">{exam.updatedBy ? exam.updatedBy : ''}</Box>
                        <Box component="span" sx={{ color: 'text.disabled' }}>
                          {exam.updatedDate ? dateHelper.formatDateTime(exam.updatedDate) : '-'}
                        </Box>
                      </Stack>
                    </TableCell>
                    <TableCell align="center">
                      <Stack direction="row" spacing={1} justifyContent="center">
                        <Button
                          component={RouterLink}
                          href={paths.dashboard.exam.marks(exam.examId)}
                          state={{
                            classId: selectedClass ? selectedClass.classId : null,
                            sectionId: selectedClass ? selectedClass.sectionId : null,
                            examName: exam.examName,
                          }}
                          size="small"
                          variant="outlined"
                        >
                          Enter Marks
                        </Button>
                        {!isExamEnded(exam) && (
                          <>
                            <Tooltip title="Edit">
                              <IconButton
                                component={RouterLink}
                                href={paths.dashboard.exam.edit(exam.examId)}
                                size="small"
                              >
                                <Iconify icon="solar:pen-bold" />
                              </IconButton>
                            </Tooltip>
                            <Tooltip title="Delete">
                              <IconButton
                                size="small"
                                color="error"
                                onClick={() => setDeleteExam(exam)}
                              >
                                <Iconify icon="solar:trash-bin-trash-bold" />
                              </IconButton>
                            </Tooltip>
                          </>
                        )}
                      </Stack>
                    </TableCell>
                  </TableRow>
                ))}
              </TableBody>
            </Table>
          </TableContainer>
        )}
      </Card>

      <ConfirmDialog
        open={Boolean(deleteExam)}
        onClose={() => setDeleteExam(null)}
        title="Delete Exam"
        content={
          deleteExam && deleteExam.examName
            ? `Are you sure you want to delete ${deleteExam.examName}?`
            : 'Are you sure you want to delete this exam?'
        }
        action={
          <Button
            variant="contained"
            color="error"
            onClick={() => {
              handleDelete(deleteExam);
              setDeleteExam(null);
            }}
          >
            Delete
          </Button>
        }
      />
    </DashboardContent>
  );
}

import { useState, useEffect } from 'react';
import { useForm } from 'react-hook-form';
import { zodResolver } from '@hookform/resolvers/zod';
import { z as zod } from 'zod';
import {
  Stack,
  Button,
  Dialog,
  MenuItem,
  Typography,
  DialogTitle,
  DialogActions,
  DialogContent,
} from '@mui/material';
import LoadingButton from '@mui/lab/LoadingButton';
import ApiService from 'src/services/ApiService';
import { toast } from 'src/components/snackbar';
import { Form, Field } from 'src/components/hook-form';
import constants from 'src/utils/constants';
import { fNumber } from 'src/utils/format-number';

const FeeCollectSchema = zod.object({
  amount: zod.coerce.number().min(0.01, { message: 'Enter a valid amount.' }),
  paymentMode: zod.string().min(1, { message: 'Payment mode is required.' }),
  paymentDate: zod.string().min(1, { message: 'Payment date is required.' }),
  remarks: zod.string().trim().optional().nullable(),
});

const defaultValues = {
  amount: '',
  paymentMode: 'CASH',
  paymentDate: '',
  remarks: '',
};

export function FeeCollectDialog({ open, onClose, student, onSuccess }) {
  const [saving, setSaving] = useState(false);

  const methods = useForm({
    resolver: zodResolver(FeeCollectSchema),
    defaultValues,
  });

  const {
    reset,
    handleSubmit,
    formState: { isSubmitting },
  } = methods;

  useEffect(() => {
    if (open && student) {
      const due = Number(student.dueAmount) || 0;
      reset({
        amount: due > 0 ? due : '',
        paymentMode: 'CASH',
        paymentDate: today(),
        remarks: '',
      });
    }
  }, [open, student, reset]);

  const handleSave = handleSubmit(async (values) => {
    setSaving(true);
    try {
      const payload = {
        studentId: student.studentId,
        amount: Number(values.amount),
        paymentDate: values.paymentDate,
        paymentMode: values.paymentMode,
        remarks: values.remarks || null,
      };
      const res = await ApiService.collectFeePaymentAsync(payload);
      if (res && res.data) {
        toast.success(`Payment collected. Receipt: ${res.data}`);
        onSuccess();
        onClose();
      } else if (res && res.errors && res.errors.length) {
        toast.error(res.errors[0].msg);
      }
    } catch (err) {
      console.error('Failed to collect payment:', err);
      toast.error('Failed to collect payment.');
    } finally {
      setSaving(false);
    }
  });

  return (
    <Dialog open={open} onClose={onClose} maxWidth="xs" fullWidth>
      <DialogTitle sx={{ fontWeight: 'bold' }}>Collect Fee</DialogTitle>
      <Form methods={methods} onSubmit={handleSave}>
        <DialogContent>
          <Stack spacing={2.5}>
            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
              {student && student.studentName ? student.studentName : ''} &nbsp;•&nbsp; Due:{' '}
              {student && student.dueAmount ? fNumber(student.dueAmount) : 0}
            </Typography>

            <Field.Text name="amount" type="number" label="Amount" fullWidth />

            <Field.Select name="paymentMode" label="Payment Mode" fullWidth>
              {constants.PAYMENT_MODES.map((mode) => (
                <MenuItem key={mode} value={mode}>
                  {mode}
                </MenuItem>
              ))}
            </Field.Select>

            <Field.DatePicker
              name="paymentDate"
              label="Payment Date"
              allowFutureDates
              allowPastDates
              slotProps={{ textField: { fullWidth: true } }}
            />

            <Field.Text name="remarks" label="Remarks" placeholder="Optional" fullWidth />
          </Stack>
        </DialogContent>
        <DialogActions sx={{ justifyContent: 'flex-start' }}>
          <LoadingButton
            type="submit"
            variant="contained"
            color="primary"
            loading={saving || isSubmitting}
          >
            Collect
          </LoadingButton>
          <Button variant="outlined" color="error" onClick={onClose}>
            Cancel
          </Button>
        </DialogActions>
      </Form>
    </Dialog>
  );
}

