import { useState, useEffect, useCallback } from 'react';
import {
  Box,
  Card,
  Table,
  Stack,
  Button,
  Switch,
  Select,
  TableRow,
  MenuItem,
  TableBody,
  TableCell,
  TableHead,
  Typography,
  TableContainer,
  CircularProgress,
  FormControlLabel,
} from '@mui/material';
import { paths } from 'src/routes/paths';
import ApiService from 'src/services/ApiService';
import { toast } from 'src/components/snackbar';
import { Iconify } from 'src/components/iconify';
import { DashboardContent } from 'src/layouts/dashboard';
import { CustomBreadcrumbs } from 'src/components/custom-breadcrumbs';
import { formatClassSection } from 'src/utils/utils';

import { TimetableEditDialog } from '../timetable-edit-dialog';

function formatTime(value) {
  if (!value) return '';
  let hours;
  let minutes;
  if (Array.isArray(value)) {
    [hours, minutes] = value;
  } else if (typeof value === 'string') {
    const [h, m] = value.split(':');
    hours = Number(h);
    minutes = Number(m);
  } else {
    return '';
  }
  if (Number.isNaN(hours) || Number.isNaN(minutes)) return '';
  const period = hours >= 12 ? 'PM' : 'AM';
  const hour12 = hours % 12 === 0 ? 12 : hours % 12;
  return `${String(hour12).padStart(2, '0')}:${String(minutes).padStart(2, '0')} ${period}`;
}

function getRowTimeLabel(row) {
  const range = [formatTime(row.startTime), formatTime(row.endTime)].filter(Boolean).join(' - ');
  return range || row.slotName || '';
}


export function TimetableView() {
  const [classSections, setClassSections] = useState([]);
  const [selectedClass, setSelectedClass] = useState(null);

  const [workingDays, setWorkingDays] = useState([]);
  const [workingDayMap, setWorkingDayMap] = useState({});
  const [subjects, setSubjects] = useState([]);

  const [rows, setRows] = useState([]);
  const [showTeacherName, setShowTeacherName] = useState(true);
  const [loading, setLoading] = useState(false);

  const [editOpen, setEditOpen] = useState(false);
  const [editRow, setEditRow] = useState(null);
  const [editDay, setEditDay] = useState('');

  useEffect(() => {
    async function loadLookups() {
      const [classRes, wdRes] = await Promise.all([
        ApiService.getAllClassMasterSectionsAsync(),
        ApiService.getWorkingDaysAsync(),
      ]);

      const classList = classRes && classRes.data ? classRes.data : [];
      setClassSections(classList);
      if (classList.length > 0) {
        setSelectedClass(classList[0]);
      }

      const map = {};
      const wdList = wdRes && wdRes.data ? wdRes.data : [];
      wdList.forEach((wd) => {
        map[wd.dayName] = wd.workingDayId;
      });
      setWorkingDayMap(map);
    }
    loadLookups();
  }, []);

  const loadTimetable = useCallback(async () => {
    if (!selectedClass) {
      setRows([]);
      setWorkingDays([]);
      setSubjects([]);
      return;
    }
    setLoading(true);
    // Only load subjects assigned to this class (set at class level), not all subjects.
    const [res, subRes] = await Promise.all([
      ApiService.getTimetableAsync(selectedClass.classId, selectedClass.sectionId),
      ApiService.getClassSubjectsAsync(selectedClass.classId),
    ]);
    const workingDaysList = res && res.data && res.data.workingDays ? res.data.workingDays : [];
    const rowsList = res && res.data && res.data.rows ? res.data.rows : [];
    setWorkingDays(workingDaysList);
    setRows(rowsList);
    setSubjects(subRes && subRes.data ? subRes.data : []);
    setLoading(false);
  }, [selectedClass]);

  useEffect(() => {
    loadTimetable();
  }, [loadTimetable]);

  const handleOpenCell = (row, day) => {
    const workingDayId = workingDayMap[day];
    if (!workingDayId) {
      toast.error(`Working day "${day}" is not configured.`);
      return;
    }
    setEditRow(row);
    setEditDay(day);
    setEditOpen(true);
  };

  const handleExport = () => {
    const csvRows = [];
    csvRows.push(['Time / Day', ...workingDays].join(','));

    rows.forEach((row) => {
      const timeLabel = getRowTimeLabel(row);
      if (row.isBreak) {
        csvRows.push(
          [timeLabel, ...Array(workingDays.length).fill(row.slotName || 'Break')].join(',')
        );
      } else {
        const line = [
          timeLabel,
          ...workingDays.map((day) => {
            const cell = row.cells && row.cells[day] ? row.cells[day] : null;
            if (!cell || !cell.subjectName) return '--';
            return showTeacherName && cell.teacherName
              ? `"${cell.subjectName} (${cell.teacherName})"`
              : `"${cell.subjectName}"`;
          }),
        ];
        csvRows.push(line.join(','));
      }
    });

    const csvContent = 'data:text/csv;charset=utf-8,' + csvRows.join('\n');
    const encodedUri = encodeURI(csvContent);
    const label = selectedClass ? getClassLabel(selectedClass) : 'Timetable';
    const link = document.createElement('a');
    link.setAttribute('href', encodedUri);
    link.setAttribute('download', `${label.replace(/\s+/g, '_')}_Timetable.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
    toast.success('Timetable exported successfully!');
  };

  const headerTitle = selectedClass ? `${getClassLabel(selectedClass)} Timetable` : 'Timetable';

  return (
    <DashboardContent>
      <CustomBreadcrumbs
        heading="Manage Timetable"
        links={[
          { name: 'Dashboard', href: '' },
          { name: 'Timetable', href: paths.dashboard.timetable.root },
        ]}
        sx={{ mb: 4 }}
      />

      <Stack
        direction={{ xs: 'column', sm: 'row' }}
        justifyContent="space-between"
        alignItems={{ xs: 'stretch', sm: 'flex-end' }}
        spacing={2}
        sx={{ mb: 3 }}
      >
        <Select
          size="small"
          value={
            selectedClass
              ? `${selectedClass.classId}-${selectedClass.sectionId !== null && selectedClass.sectionId !== undefined ? selectedClass.sectionId : 'null'}`
              : ''
          }
          onChange={(e) => {
            const val = e.target.value;
            if (!val) {
              setSelectedClass(null);
            } else {
              const [classId, sectionId] = val.split('-');
              const selectedOption = classSections.find(
                (c) =>
                  c.classId == classId &&
                  (c.sectionId !== null && c.sectionId !== undefined ? c.sectionId : 'null') ==
                    sectionId
              );
              setSelectedClass(selectedOption || null);
            }
          }}
          displayEmpty
          sx={{ minWidth: 200, textAlign: 'left' }}
        >
          <MenuItem value="" disabled>
            <em>Select Class & Section</em>
          </MenuItem>
          {classSections.map((option) => (
            <MenuItem
              key={`${option.classId}-${option.sectionId !== null && option.sectionId !== undefined ? option.sectionId : 'null'}`}
              value={`${option.classId}-${option.sectionId !== null && option.sectionId !== undefined ? option.sectionId : 'null'}`}
            >
              {formatClassSection(option)}
            </MenuItem>
          ))}
        </Select>

        <Button
          variant="contained"
          color="primary"
          startIcon={<Iconify icon="solar:download-linear" />}
          onClick={handleExport}
          disabled={rows.length === 0}
        >
          Export
        </Button>
      </Stack>

      <Card>
        <Stack direction="row" alignItems="center" sx={{ p: 2 }}>
          <Stack>
            <Typography variant="h6" sx={{ fontWeight: 'bold' }}>
              {headerTitle}
            </Typography>
          </Stack>
        </Stack>

        {loading ? (
          <Box sx={{ display: 'flex', justifyContent: 'center', alignItems: 'center', py: 10 }}>
            <CircularProgress color="success" />
          </Box>
        ) : rows.length === 0 ? (
          <Box sx={{ py: 10, textAlign: 'center' }}>
            <Typography variant="body2" sx={{ color: 'text.secondary' }}>
              No data found
            </Typography>
          </Box>
        ) : (
          <>
            <TableContainer sx={{ overflowX: 'auto' }}>
              <Table
                size="small"
                sx={{
                  minWidth: 800,
                  tableLayout: 'fixed',
                  borderCollapse: 'collapse',
                  '& th, & td': {
                    borderRight: '1px solid',
                    borderBottom: '1px solid',
                    borderColor: 'divider',
                    textAlign: 'center',
                  },
                  '& th:last-of-type, & td:last-of-type': {
                    borderRight: 0,
                  },
                }}
              >
                <TableHead>
                  <TableRow>
                    <TableCell
                      sx={{
                        fontWeight: 800,
                        width: '180px',
                        color: 'text.secondary',
                        textTransform: 'uppercase',
                        letterSpacing: 0.5,
                      }}
                    >
                      Time / Day
                    </TableCell>
                    {workingDays.map((day) => (
                      <TableCell
                        key={day}
                        sx={{
                          fontWeight: 800,
                          color: 'text.secondary',
                          textTransform: 'uppercase',
                          letterSpacing: 0.5,
                          width: '150px',
                        }}
                      >
                        {day}
                      </TableCell>
                    ))}
                  </TableRow>
                </TableHead>

                <TableBody>
                  {rows.map((row) => (
                    <TableRow key={row.timeSlotId} hover>
                      <TableCell
                        sx={{
                          fontWeight: 700,
                          color: 'text.secondary',
                          lineHeight: 1.2,
                        }}
                      >
                        {getRowTimeLabel(row)}
                      </TableCell>

                      {row.isBreak ? (
                        <TableCell colSpan={workingDays.length}>
                          <Typography
                            variant="subtitle2"
                            sx={{
                              fontWeight: 800,
                              letterSpacing: 1.5,
                              textAlign: 'center',
                            }}
                          >
                            BREAK
                          </Typography>
                        </TableCell>
                      ) : (
                        workingDays.map((day) => {
                          const cell = row.cells && row.cells[day] ? row.cells[day] : null;
                          const hasClass = Boolean(cell && cell.subjectName);

                          return (
                            <TableCell
                              key={day}
                              onClick={() => handleOpenCell(row, day)}
                              sx={{
                                verticalAlign: 'middle',
                                cursor: 'pointer',
                              }}
                            >
                              {hasClass ? (
                                <Stack alignItems="center" justifyContent="center">
                                  <Typography
                                    variant="subtitle2"
                                    sx={{
                                      fontWeight: 700,
                                      color: 'text.primary',
                                      lineHeight: 1.2,
                                    }}
                                  >
                                    {cell.subjectName}
                                  </Typography>
                                  {showTeacherName && cell.teacherName && (
                                    <Typography
                                      variant="caption"
                                      sx={{
                                        color: 'text.secondary',
                                        fontWeight: 500,
                                      }}
                                    >
                                      {cell.teacherName}
                                    </Typography>
                                  )}
                                </Stack>
                              ) : (
                                <Typography
                                  variant="body2"
                                  sx={{ color: 'text.disabled', opacity: 0.4 }}
                                >
                                  --
                                </Typography>
                              )}
                            </TableCell>
                          );
                        })
                      )}
                    </TableRow>
                  ))}
                </TableBody>
              </Table>
            </TableContainer>

            <Box
              sx={{
                p: 1.5,
                display: 'flex',
                alignItems: 'center',
                borderTop: '1px solid',
                borderColor: 'divider',
              }}
            >
              <FormControlLabel
                control={
                  <Switch
                    checked={showTeacherName}
                    onChange={(e) => setShowTeacherName(e.target.checked)}
                  />
                }
                label="Show Teacher Name"
                sx={{ ml: 1 }}
              />
            </Box>
          </>
        )}
      </Card>

      <TimetableEditDialog
        open={editOpen}
        onClose={() => setEditOpen(false)}
        row={editRow}
        day={editDay}
        subjects={subjects}
        selectedClass={selectedClass}
        workingDayId={workingDayMap[editDay]}
        onSuccess={loadTimetable}
      />
    </DashboardContent>
  );
}

import constants from './constants.js';

// #region localStorage
const setItemToStorage = (key, value) => {
  localStorage.setItem(key, value);
};

const getItemFromStorage = (key) => {
  const item = localStorage.getItem(key);
  if (item) {
    return item;
  }

  return null;
};

const removeItem = (key) => localStorage.removeItem(key);

const clearLocalStorage = () => localStorage.clear();

const setTokensToStorage = (token) => {
  localStorage.setItem(constants.localStorageKey.tokens, btoa(JSON.stringify(token)));
};

const getTokensFromStorage = () => {
  const item = localStorage.getItem(constants.localStorageKey.tokens);
  if (item) {
    const token = JSON.parse(atob(item));
    return token;
  }

  return null;
};
// #endregion

const handleConfirmDelete = async ({ setLoading, onDeleteRow, confirmDialog }) => {
  setLoading(true);
  await onDeleteRow();
  confirmDialog.onFalse();
  setLoading(false);
};

export const formatClassSection = (option, fallback = '') => {
  if (!option) return fallback;
  if (typeof option === 'string') return option;
  if (option.className) {
    return option.sectionName
      ? `${option.className} - ${option.sectionName}`
      : option.className;
  }
  return fallback;
};

export const getFullName = (person, fallback = '') => {
  if (!person) return fallback;
  if (typeof person === 'string') return person;
  if (person.studentName) return person.studentName;
  if (person.teacherName) return person.teacherName;
  if (person.fullName) return person.fullName;
  if (person.name) return person.name;
  if (person.firstName || person.lastName) {
    const parts = [];
    if (person.firstName) parts.push(person.firstName);
    if (person.lastName) parts.push(person.lastName);
    return parts.join(' ');
  }
  return fallback;
};

export const getInitials = (name) => {
  if (!name) return '';
  const str = String(name).trim();
  return str ? str.charAt(0).toUpperCase() : '';
};

export const formatTimeSlice = (timeStr) => {
  if (!timeStr) return '';
  return String(timeStr).slice(0, 5);
};

export default {
  setItemToStorage,
  getItemFromStorage,
  removeItem,
  setTokensToStorage,
  getTokensFromStorage,
  clearLocalStorage,
  handleConfirmDelete,
  formatClassSection,
  getFullName,
  getInitials,
  formatTimeSlice,
};
